True def transform(grid):
    g=[row[:] for row in grid]
    bg=9
    h,w=len(g),len(g[0])
    hcuts=[-1]+[r for r in range(h) if len(set(g[r]))==1 and g[r][0]!=bg]+[h]
    wcuts=[-1]+[c for c in range(w) if len({g[r][c] for r in range(h)})==1 and g[0][c]!=bg]+[w]
    rowspans=[(hcuts[i]+1,hcuts[i+1]) for i in range(len(hcuts)-1)]
    colspans=[(wcuts[i]+1,wcuts[i+1]) for i in range(len(wcuts)-1)]
    source=None
    for r0,r1 in rowspans:
        for c0,c1 in colspans:
            pat=[row[c0:c1] for row in g[r0:r1]]
            if any(v!=bg for row in pat for v in row):
                source=pat
                break
        if source is not None: break
    if source is None: return g
    for r0,r1 in rowspans:
        for c0,c1 in colspans:
            if r1-r0==len(source) and c1-c0==len(source[0]):
                for i in range(len(source)):
                    g[r0+i][c0:c1]=source[i][:]
    return g
